import styles from "./page.module.css";

type RunMetadata = {
  status?: string;
  tokenId?: string;
  email?: string;
};

type RunResponse = {
  id: string;
  status: string;
  metadata: RunMetadata;
};

export default function Home() {
  const [email, setEmail] = useState("");
  const [runId, setRunId] = useState<string | null>(null);
  const [runStatus, setRunStatus] = useState<string | null>(null);
  const [metadata, setMetadata] = useState<RunMetadata>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!runId) {
      return;
    }

    let isMounted = true;

    const pollRun = async () => {
      try {
        const response = await fetch(`/api/run?runId=${encodeURIComponent(runId)}`);
        if (!response.ok) {
          return;
        }

        const data = (await response.json()) as RunResponse;
        if (!isMounted) {
          return;
        }

        setRunStatus(data.status);
        setMetadata(data.metadata ?? {});
      } catch {
        // Ignore polling errors.
      }
    };

    pollRun();
    const intervalId = window.setInterval(pollRun, 2000);

    return () => {
      isMounted = false;
      window.clearInterval(intervalId);
    };
  }, [runId]);

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);
    setIsSubmitting(true);

    try {
      const response = await fetch("/api/start", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email }),
      });

      if (!response.ok) {
        const data = (await response.json()) as { error?: string };
        throw new Error(data.error ?? "Unable to start onboarding.");
      }

      const data = (await response.json()) as { runId: string };
      setRunId(data.runId);
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : "Unknown error");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleVerify = async () => {
    if (!metadata.tokenId) {
      return;
    }

    await fetch(`/api/verify?token=${encodeURIComponent(metadata.tokenId)}`, {
      method: "POST",
    });
  };

  return (
    <div className={styles.page}>
      <main className={styles.main}>
        <header className={styles.header}>
          <h1>Durable Subscription Onboarding</h1>
          <p>Trigger a wait

